   END IF;
  END LOOP;
  actual_hash:=LOWER(RAWTOHEX(DBMS_CRYPTO.HASH(source_text,DBMS_CRYPTO.HASH_SH256)));
  IF DBMS_LOB.ISTEMPORARY(source_text)=1 THEN DBMS_LOB.FREETEMPORARY(source_text);END IF;
